-- Test fixtures for the internal catalogue. Distances are published approximations.
-- Assumed rates are kept in notes and cannot be used as supplier prices.
INSERT INTO destinations (country, city, verticals)
SELECT 'Saudi Arabia', city, '["umrah", "hajj"]'::jsonb
FROM (VALUES ('Makkah'), ('Madinah')) AS requested(city)
WHERE NOT EXISTS (
  SELECT 1 FROM destinations d WHERE lower(d.city) = lower(requested.city)
    AND lower(d.country) IN ('saudi arabia', 'ksa')
)
ON CONFLICT (country, city) DO NOTHING;
