INSERT INTO hotels (name, destination_id, star_rating, distance_to_haram_m, area, road, location_aliases, distance_reference, notes, is_active)
SELECT sample.name, d.id, stars, metres, area, road, aliases, landmark, notes, false
FROM sample
CROSS JOIN LATERAL (
  SELECT id FROM destinations
  WHERE lower(destinations.city) = lower(sample.city) AND lower(country) IN ('saudi arabia', 'ksa')
  ORDER BY (destinations.city = sample.city) DESC, is_active DESC, id LIMIT 1
) d
WHERE NOT EXISTS (
  SELECT 1 FROM hotels h WHERE h.destination_id = d.id AND lower(h.name) = lower(sample.name)
);
